from __future__ import annotations


def control_page_html() -> str:
    return r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MetaTrader AI Bridge Control</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{font-family:system-ui,sans-serif;background:#111827;color:#e5e7eb;margin:0;padding:24px}.wrap{max-width:1160px;margin:auto}.card{background:#1f2937;border:1px solid #374151;border-radius:16px;padding:20px;margin:14px 0}.row{display:grid;grid-template-columns:220px 1fr 80px;gap:14px;align-items:center;margin:14px 0}.fields{display:grid;grid-template-columns:repeat(3,minmax(140px,1fr));gap:12px}.field label{display:block;color:#9ca3af;font-size:13px;margin-bottom:6px}.field input{width:100%;background:#111827;color:white;border:1px solid #4b5563;border-radius:8px;padding:9px}.nav a,.linkbtn{color:#bfdbfe;text-decoration:none;border:1px solid #374151;border-radius:10px;padding:9px 12px;display:inline-block}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}button{background:#2563eb;color:white;border:0;border-radius:10px;padding:11px 18px;font-weight:700;cursor:pointer}button.recommended{background:#0f766e}button.research{background:#b45309}button:disabled{opacity:.5}.ok{color:#4ade80}.bad{color:#fb7185}.warn{color:#fbbf24}.muted{color:#9ca3af}code{color:#93c5fd}.metrics{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:10px;margin-top:16px}.metric{background:#111827;border:1px solid #374151;border-radius:12px;padding:12px}.metric b{display:block;font-size:22px;margin-top:4px}.statusbox{background:#111827;border:1px solid #374151;border-radius:12px;padding:14px;margin-top:12px;line-height:1.55}.tablewrap{overflow:auto;margin-top:14px}table{width:100%;border-collapse:collapse;min-width:900px}th,td{padding:9px;border-bottom:1px solid #374151;text-align:left;font-size:13px}th{color:#9ca3af}.comparetable{min-width:720px}.comparetable td:nth-child(2),.comparetable td:nth-child(3),.comparetable td:nth-child(4){font-variant-numeric:tabular-nums}.pill{display:inline-block;border:1px solid #4b5563;border-radius:999px;padding:3px 8px;font-size:12px;margin-left:6px}.summaryline{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}.tip{position:relative;display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;margin-left:6px;border:1px solid #64748b;border-radius:50%;font-size:11px;font-weight:800;color:#cbd5e1;cursor:help;vertical-align:middle;outline:none}.tip:hover,.tip:focus{border-color:#60a5fa;color:#dbeafe}.tip:hover::after,.tip:focus::after{content:attr(data-tip);position:absolute;left:50%;bottom:calc(100% + 9px);transform:translateX(-50%);width:250px;padding:9px 11px;border:1px solid #475569;border-radius:9px;background:#020617;color:#f8fafc;font-size:12px;font-weight:500;line-height:1.65;direction:rtl;text-align:right;white-space:normal;z-index:9999;box-shadow:0 10px 28px rgba(0,0,0,.35)}.tip:hover::before,.tip:focus::before{content:"";position:absolute;bottom:calc(100% + 3px);left:50%;transform:translateX(-50%);border:6px solid transparent;border-top-color:#475569;z-index:9999}@media(max-width:900px){.fields,.metrics{grid-template-columns:1fr 1fr}}@media(max-width:700px){body{padding:12px}.row{grid-template-columns:1fr}.fields,.metrics{grid-template-columns:1fr}}
</style></head><body><div class="wrap">
<h1>MetaTrader AI v2 — Bridge Control</h1><p class="muted">Live explainable thresholds, continuous historical replay and independent LONA validation.</p><div class="nav"><a href="/train">Open Training Lab →</a></div>
<div class="card" id="factors"></div>
<div class="card"><h2>Decision & execution gates</h2><div class="row"><label>Minimum passed factors</label><input id="min_pass_count" type="range" min="1" max="6"><input id="min_pass_count_n" type="number" min="1" max="6"></div><div class="row"><label>Minimum total score</label><input id="min_total_score" type="range" min="0" max="100"><input id="min_total_score_n" type="number" min="0" max="100"></div><div class="row"><label>Minimum BUY/SELL edge</label><input id="min_side_edge" type="range" min="0" max="100"><input id="min_side_edge_n" type="number" min="0" max="100"></div><div class="row"><label>Max concurrent trades</label><input id="max_open_trades" type="range" min="1" max="5" step="1"><input id="max_open_trades_n" type="number" min="1" max="5" step="1"></div><div class="row"><label>Live risk / trade %</label><input id="risk_percent" type="range" min="0.05" max="5" step="0.05"><input id="risk_percent_n" type="number" min="0.05" max="5" step="0.05"></div><div class="row"><label>Live Reward : Risk</label><input id="reward_risk_ratio" type="range" min="0.5" max="10" step="0.1"><input id="reward_risk_ratio_n" type="number" min="0.5" max="10" step="0.1"></div><p class="muted">Live effective position cap = min(Bridge value, EA local <code>MaxOpenTrades</code>). Risk and R:R are sent by the Bridge to EA v0.23+.</p></div>
<p class="actions"><button id="saveBtn">Save live settings</button><button id="researchPresetBtn" class="research">Apply Research Candidate 55/50/45</button><span id="status"></span></p><p class="muted">Research preset: Dynamic 55 · Static 50 · Fibonacci/Patterns/Pivots/Divergence 45 · passed 2 · total 43 · edge 7 · max 1 · risk 0.5% · RR 2. It is a research candidate, not a profitability guarantee.</p>
<div class="card"><h2>Model-recommended profile</h2><p id="recommendInfo" class="muted">Checking recommendation…</p><p><button id="recommendBtn" class="recommended">Apply model-recommended settings</button> <span id="recommendStatus"></span></p><p class="muted">Recommended profile changes analysis thresholds only. Execution settings such as max concurrent trades, live risk and R:R are preserved.</p></div>
<div class="card"><h2>LONA independent validation</h2><p class="muted">Cross-checks our six-factor strategy using an independent Backtrader implementation. This does not replace MT5 forward testing.</p><div id="lonaStatus" class="statusbox muted">Reading latest LONA status…</div><div id="lonaMetrics"></div><div class="actions" style="margin-top:12px"><a class="linkbtn" href="/history/export.csv?symbol=XAUUSD_o&timeframe=M15">Download MT5 M15 CSV for LONA</a><button id="refreshLona">Refresh LONA result</button></div></div>
<div class="card"><h2>Our Model vs LONA</h2><p class="muted">Parity mode now uses one continuous Python replay: positions can remain open across broker-day boundaries. The comparison also forces our canonical Stable Baseline so it is not accidentally compared with edited live thresholds.</p><div id="compareStatus" class="statusbox muted">Waiting for LONA and our continuous replay result…</div><div class="actions" style="margin-top:12px"><button id="runLonaPeriod" class="recommended" disabled>Run continuous parity on LONA period</button><span id="compareMsg" class="muted"></span></div><div id="compareResult"></div></div>
<div class="card"><h2>Historical continuous range replay</h2><p class="muted">Unlike the old day-by-day replay, positions are not force-closed at midnight. Only positions still open on the final bar are marked as <code>RANGE_CLOSE</code>.</p><p id="historyStatus" class="muted">Checking MT5 history…</p><div class="fields"><div class="field"><label>Start date</label><input id="btStartDate" type="date"></div><div class="field"><label>End date</label><input id="btEndDate" type="date"></div><div class="field"><label>Starting balance $</label><input id="btBalance" type="number" min="10" value="1000"></div><div class="field"><label>Risk / trade %</label><input id="btRisk" type="number" min="0.01" max="5" step="0.05" value="0.5"></div><div class="field"><label>Reward : Risk</label><input id="btRR" type="number" min="0.5" max="10" step="0.1" value="2"></div><div class="field"><label>Max concurrent trades</label><input id="btMaxOpen" type="number" min="1" max="5" step="1" value="1"></div></div><p><button id="runBt" disabled>Run continuous range</button> <span id="btMsg" class="muted"></span></p><div id="btResult"></div></div>
</div><script>
const factors=['dynamic_levels','static_levels','fibonacci','patterns','pivots','divergence'];
const paramTips={
 dynamic_levels:'حداقل امتیاز روند، EMAها و موقعیت قیمت برای تأیید این فاکتور.',
 static_levels:'حداقل امتیاز حمایت/مقاومت و نشانه‌های Order Block.',
 fibonacci:'حداقل امتیاز نزدیکی قیمت به سطوح مهم فیبوناچی.',
 patterns:'حداقل امتیاز الگوهای کندلی و هارمونیک مثل AB=CD.',
 pivots:'حداقل امتیاز واکنش قیمت به Pivot و سطوح روز قبل.',
 divergence:'حداقل امتیاز واگرایی و مومنتوم RSI/MACD.',
 min_pass_count:'حداقل تعداد فاکتورهایی که باید هم‌زمان تأیید شوند.',
 min_total_score:'حداقل امتیاز کلی سمت BUY یا SELL برای ورود.',
 min_side_edge:'حداقل فاصله امتیاز BUY و SELL تا جهت بازار واضح باشد.',
 max_open_trades:'حداکثر تعداد پوزیشن‌های هم‌زمان که ربات اجازه دارد باز نگه دارد.',
 risk_percent:'درصد Equity که EA برای حد ضرر هر معامله ریسک می‌کند.',
 reward_risk_ratio:'نسبت Take Profit به Stop Loss؛ ۲ یعنی هدف سود دو برابر ریسک.',
 btStartDate:'اولین روزی که در بک‌تست بررسی می‌شود.',
 btEndDate:'آخرین روزی که در بک‌تست بررسی می‌شود.',
 btBalance:'سرمایه فرضی ابتدای بک‌تست برای محاسبه سود و ضرر.',
 btRisk:'درصد سرمایه‌ای که در هر معامله در معرض ریسک قرار می‌گیرد.',
 btRR:'نسبت سود هدف به ریسک؛ ۲ یعنی هدف سود دو برابر حد ضرر است.',
 btMaxOpen:'حداکثر تعداد معاملات باز هم‌زمان در این بک‌تست.'
};
let cfg,dates=[],lonaData=null,lastReplay=null;
const $=id=>document.getElementById(id);
function bind(id,value){$(id).value=value;$(id+'_n').value=value;$(id).oninput=()=>$(id+'_n').value=$(id).value;$(id+'_n').oninput=()=>$(id).value=$(id+'_n').value}
function setBound(id,value){$(id).value=value;$(id+'_n').value=value}
function attachTooltips(){for(const [id,text] of Object.entries(paramTips)){const el=$(id);if(!el)continue;const holder=el.closest('.row')||el.closest('.field');const label=holder?holder.querySelector('label'):null;if(!label||label.querySelector('.tip'))continue;const tip=document.createElement('span');tip.className='tip';tip.tabIndex=0;tip.dataset.tip=text;tip.textContent='؟';label.appendChild(tip)}}
function money(v){const n=Number(v)||0;return `${n<0?'-$':'$'}${Math.abs(n).toFixed(2)}`}
function metric(label,value,sub=''){return `<div class="metric"><span class="muted">${label}</span><b>${value}</b><small>${sub}</small></div>`}
function time(x){return new Date(x*1000).toISOString().replace('T',' ').slice(0,16)}
function finite(v){const n=Number(v);return Number.isFinite(n)?n:0}
function signed(v,d=2,suffix=''){const n=finite(v);return `${n>0?'+':''}${n.toFixed(d)}${suffix}`}
function deltaClass(v,lowerBetter=false){const n=finite(v);if(Math.abs(n)<1e-9)return 'muted';return (lowerBetter?n<0:n>0)?'ok':'bad'}
function pfText(v){return v===null||v===undefined?'—':finite(v).toFixed(2)}

async function load(){cfg=await(await fetch('/strategy/config')).json();$('factors').innerHTML='<h2>Factor minimums</h2>'+factors.map(n=>`<div class="row"><label>${n.replaceAll('_',' ')}</label><input id="${n}" type="range" min="0" max="100"><input id="${n}_n" type="number" min="0" max="100"></div>`).join('');for(const n of factors)bind(n,cfg[n].min_score);bind('min_pass_count',cfg.decision.min_pass_count);bind('min_total_score',cfg.decision.min_total_score);bind('min_side_edge',cfg.decision.min_side_edge);bind('max_open_trades',cfg.safety.max_open_trades||1);bind('risk_percent',cfg.safety.risk_percent||0.5);bind('reward_risk_ratio',cfg.safety.reward_risk_ratio||2);$('btMaxOpen').value=cfg.safety.max_open_trades||1;$('btRisk').value=cfg.safety.risk_percent||0.5;$('btRR').value=cfg.safety.reward_risk_ratio||2;attachTooltips();await Promise.all([history(),recommend(),loadLona()]);updateCompareButton()}
async function save(){for(const n of factors)cfg[n].min_score=Number($(n).value);cfg.decision.min_pass_count=Number($('min_pass_count').value);cfg.decision.min_total_score=Number($('min_total_score').value);cfg.decision.min_side_edge=Number($('min_side_edge').value);cfg.safety.max_open_trades=Number($('max_open_trades').value);cfg.safety.risk_percent=Number($('risk_percent').value);cfg.safety.reward_risk_ratio=Number($('reward_risk_ratio').value);const r=await fetch('/strategy/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(cfg)});$('status').textContent=r.ok?'Saved':'Save failed';$('status').className=r.ok?'ok':'bad';if(r.ok){cfg=await r.json();$('btMaxOpen').value=cfg.safety.max_open_trades;$('btRisk').value=cfg.safety.risk_percent;$('btRR').value=cfg.safety.reward_risk_ratio}return r.ok}
async function applyResearchPreset(){const vals={dynamic_levels:55,static_levels:50,fibonacci:45,patterns:45,pivots:45,divergence:45};for(const [id,value] of Object.entries(vals))setBound(id,value);setBound('min_pass_count',2);setBound('min_total_score',43);setBound('min_side_edge',7);setBound('max_open_trades',1);setBound('risk_percent',0.5);setBound('reward_risk_ratio',2);$('btMaxOpen').value=1;$('btRisk').value=0.5;$('btRR').value=2;$('status').textContent='Applying research preset…';$('status').className='warn';const ok=await save();if(ok){$('status').textContent='Research Candidate applied: 55/50/45/45/45/45 · 2/43/7 · max 1 · risk 0.5% · RR 2';$('status').className='ok'}}
async function recommend(){try{const d=await(await fetch('/strategy/recommended')).json();$('recommendInfo').textContent=`Source: ${d.source} · ${d.sample_size} forward trades. ${d.reasons.join(' ')}`}catch(e){$('recommendInfo').textContent=e.message}}
async function applyRec(){const r=await fetch('/strategy/apply-recommended',{method:'POST'}),d=await r.json();if(!r.ok){$('recommendStatus').textContent=d.detail||'Failed';$('recommendStatus').className='bad';return}cfg=d;for(const n of factors){$(n).value=d[n].min_score;$(n+'_n').value=d[n].min_score}for(const n of ['min_pass_count','min_total_score','min_side_edge']){$(n).value=d.decision[n];$(n+'_n').value=d.decision[n]}for(const n of ['max_open_trades','risk_percent','reward_risk_ratio'])setBound(n,d.safety[n]);$('btMaxOpen').value=d.safety.max_open_trades;$('btRisk').value=d.safety.risk_percent;$('btRR').value=d.safety.reward_risk_ratio;$('recommendStatus').textContent='Applied; execution settings preserved';$('recommendStatus').className='ok'}
function updateCompareButton(){$('runLonaPeriod').disabled=!(dates.length&&lonaData&&lonaData.requested_start&&lonaData.requested_end)}
async function loadLona(){const box=$('lonaStatus'),out=$('lonaMetrics');try{const r=await fetch('/lona/status'),d=await r.json();if(!r.ok)throw new Error(d.detail||'LONA status failed');lonaData=d;const klass=d.status==='COMPLETED'?'ok':d.status==='BLOCKED_PLAN'?'warn':'muted';box.className='statusbox '+klass;box.innerHTML=`<b>${d.status||'UNKNOWN'}</b> · ${d.strategy_name||'LONA strategy'}<br>${d.symbol||''} ${d.frequency||''} · ${d.requested_start||''} → ${d.requested_end||''}<br>${d.message||''}`;const m=d.metrics;if(m){out.innerHTML=`<div class="metrics">${metric('Return',finite(m.total_return).toFixed(2)+'%','')}${metric('Profit factor',finite(m.profit_factor).toFixed(2),'')}${metric('Max drawdown',finite(m.max_drawdown).toFixed(2)+'%','')}${metric('Win rate',finite(m.win_rate).toFixed(1)+'%','')}${metric('Trades',m.trades||0,'independent engine')}</div>`}else out.innerHTML='';updateCompareButton();renderComparison()}catch(e){lonaData=null;box.textContent=e.message;box.className='statusbox bad';out.innerHTML='';updateCompareButton();renderComparison()}}
async function history(){try{const h=await(await fetch('/history/status?symbol=XAUUSD_o&timeframe=M15')).json();if(!h.bars)throw new Error('No history synced yet');dates=(h.available_dates||[]).slice().sort();$('historyStatus').textContent=`Synced ${h.bars} bars · ${h.earliest_date} → ${h.latest_date}`;$('historyStatus').className='ok';for(const id of ['btStartDate','btEndDate']){$(id).min=h.earliest_date;$(id).max=h.latest_date}$('btEndDate').value=dates[dates.length-1];$('btStartDate').value=dates[Math.max(0,dates.length-20)];$('runBt').disabled=false;updateCompareButton()}catch(e){$('historyStatus').textContent=e.message;$('historyStatus').className='warn';updateCompareButton()}}

function normalizeRange(d,profile){return{start:d.start_date,end:d.end_date,profile,max_open_trades:d.max_open_trades,risk_percent:d.risk_percent,reward_risk_ratio:d.reward_risk_ratio,starting_balance:d.starting_balance,ending_balance:d.ending_balance,trading_days:d.trading_days,trades:d.trades,wins:d.wins,losses:d.losses,win_rate:d.win_rate,net_r:d.net_r,expectancy_r:d.expectancy_r,total_return:d.total_return_percent,profit_factor:d.profit_factor,max_drawdown_percent:d.max_drawdown_percent,max_drawdown_r:d.max_drawdown_r,pnl:d.estimated_pnl_money,avg_day:d.trading_days?d.estimated_pnl_money/d.trading_days:0,trades_detail:d.trades_detail||[]}}
function renderRangeResult(x){const shown=x.trades_detail.slice(0,500),more=x.trades_detail.length-shown.length;$('btResult').innerHTML=`<div class="metrics">${metric('Trading days',x.trading_days,'continuous')}${metric('Trades',x.trades,`${x.wins}W / ${x.losses}L`)}${metric('Win rate',finite(x.win_rate).toFixed(1)+'%',`PF ${pfText(x.profit_factor)}`)}${metric('Net R',finite(x.net_r).toFixed(2)+'R',`DD ${finite(x.max_drawdown_r).toFixed(2)}R`)}${metric('Total P/L',money(x.pnl),`${signed(x.total_return,2,'%')} · DD ${finite(x.max_drawdown_percent).toFixed(2)}%`)}</div><p class="muted">Continuous replay · ${x.profile==='MODEL_BASELINE'?'Stable Baseline':'current live thresholds'} · average/trading day ${money(x.avg_day)}.</p><h3>Trades</h3><div class="tablewrap"><table><thead><tr><th>#</th><th>Entry</th><th>Side</th><th>Exit</th><th>R</th><th>P/L</th><th>Passed</th></tr></thead><tbody>${shown.map((t,i)=>`<tr><td>${i+1}</td><td>${time(t.entry_time)}</td><td>${t.side}</td><td>${t.outcome}</td><td>${finite(t.r_multiple).toFixed(2)}R</td><td class="${t.pnl_money>=0?'ok':'bad'}">${money(t.pnl_money)}</td><td>${t.passed_count}/6</td></tr>`).join('')||'<tr><td colspan="7">No trades.</td></tr>'}</tbody></table></div>${more>0?`<p class="muted">Showing first 500 trades; ${more} more are included in the metrics.</p>`:''}`}

async function runRange(start,end,balance0,risk,rr,maxOpen,profile='CURRENT'){const q=new URLSearchParams({start_date:start,end_date:end,symbol:'XAUUSD_o',timeframe:'M15',starting_balance:String(balance0),risk_percent:String(risk),reward_risk_ratio:String(rr),max_open_trades:String(maxOpen),profile});const r=await fetch('/backtest/range?'+q),d=await r.json();if(!r.ok)throw new Error(d.detail||'Continuous range backtest failed');return normalizeRange(d,profile)}
async function replay(profile='CURRENT'){const start=$('btStartDate').value,end=$('btEndDate').value,maxOpen=Number($('btMaxOpen').value),balance0=Number($('btBalance').value),risk=Number($('btRisk').value),rr=Number($('btRR').value);if(!start||!end||start>end||maxOpen<1||maxOpen>5){$('btMsg').textContent='Check dates and concurrent limit 1–5';$('btMsg').className='bad';return null}if(!dates.some(d=>d>=start&&d<=end)){$('btMsg').textContent='No synced trading dates in this range';$('btMsg').className='bad';return null}$('runBt').disabled=true;$('runLonaPeriod').disabled=true;$('btMsg').textContent='Running continuous replay… positions may stay open across days.';$('btMsg').className='muted';try{lastReplay=await runRange(start,end,balance0,risk,rr,maxOpen,profile);$('btMsg').textContent=`Done · ${lastReplay.trading_days} trading days · continuous · max ${maxOpen} concurrent`;$('btMsg').className='ok';renderRangeResult(lastReplay);renderComparison();return lastReplay}catch(e){$('btMsg').textContent=e.message;$('btMsg').className='bad';return null}finally{$('runBt').disabled=false;updateCompareButton()}}

function renderComparison(){const box=$('compareStatus'),out=$('compareResult');if(!lonaData||!lonaData.metrics){box.className='statusbox warn';box.textContent='No completed LONA metrics are available yet.';out.innerHTML='';return}if(!lastReplay){box.className='statusbox muted';box.innerHTML=`Latest LONA window: <b>${lonaData.requested_start||'?'} → ${lonaData.requested_end||'?'}</b>. Run continuous parity to compare the same period.`;out.innerHTML='';return}const l=lonaData.metrics,o=lastReplay,samePeriod=o.start===lonaData.requested_start&&o.end===lonaData.requested_end,sameSetup=o.profile==='MODEL_BASELINE'&&o.max_open_trades===1&&Math.abs(o.risk_percent-0.5)<1e-9&&Math.abs(o.reward_risk_ratio-2)<1e-9&&Math.abs(o.starting_balance-1000)<1e-9;const dTrades=o.trades-finite(l.trades),dWr=o.win_rate-finite(l.win_rate),dPf=(o.profit_factor===null?0:finite(o.profit_factor))-finite(l.profit_factor),dRet=o.total_return-finite(l.total_return),dDd=o.max_drawdown_percent-finite(l.max_drawdown);const bothPositive=o.total_return>0&&(o.profit_factor===null||o.profit_factor>1)&&finite(l.total_return)>0&&finite(l.profit_factor)>1;box.className='statusbox '+(samePeriod&&sameSetup?'ok':'warn');box.innerHTML=`<b>${samePeriod?'Exact date window':'Date window mismatch'}</b> · ${sameSetup?'Continuous Stable-Baseline parity preset':'Replay settings/profile differ from parity preset'}<div class="summaryline"><span class="pill">No daily forced close</span><span class="pill ${bothPositive?'ok':'warn'}">${bothPositive?'Both engines profitable':'Profitability not aligned'}</span><span class="pill">Our ${o.start} → ${o.end}</span><span class="pill">LONA ${lonaData.requested_start||'?'} → ${lonaData.requested_end||'?'}</span></div>`;out.innerHTML=`<div class="tablewrap"><table class="comparetable"><thead><tr><th>Metric</th><th>Our Python engine</th><th>LONA</th><th>Our − LONA</th></tr></thead><tbody><tr><td>Trades</td><td>${o.trades}</td><td>${l.trades||0}</td><td class="muted">${signed(dTrades,0)}</td></tr><tr><td>Win rate</td><td>${finite(o.win_rate).toFixed(2)}%</td><td>${finite(l.win_rate).toFixed(2)}%</td><td class="${deltaClass(dWr)}">${signed(dWr,2,' pp')}</td></tr><tr><td>Profit factor</td><td>${pfText(o.profit_factor)}</td><td>${finite(l.profit_factor).toFixed(2)}</td><td class="${deltaClass(dPf)}">${signed(dPf,2)}</td></tr><tr><td>Total return</td><td>${signed(o.total_return,2,'%')}</td><td>${signed(l.total_return,2,'%')}</td><td class="${deltaClass(dRet)}">${signed(dRet,2,' pp')}</td></tr><tr><td>Max drawdown</td><td>${finite(o.max_drawdown_percent).toFixed(2)}%</td><td>${finite(l.max_drawdown).toFixed(2)}%</td><td class="${deltaClass(dDd,true)}">${signed(dDd,2,' pp')}</td></tr><tr><td>Expectancy</td><td>${signed(o.expectancy_r,3,'R / trade')}</td><td>${signed(l.expectancy,2,' LONA units')}</td><td class="muted">different units</td></tr></tbody></table></div><p class="muted">This removes the largest old mismatch: forced end-of-day closes. LONA is still an independent approximation, so factor implementation, spread handling and stop execution can still create differences. Expectancy units are not directly comparable.</p>`}

async function runLonaPeriod(){if(!lonaData||!dates.length)return;const availableStart=dates[0],availableEnd=dates[dates.length-1],requestedStart=lonaData.requested_start,requestedEnd=lonaData.requested_end;const start=requestedStart<availableStart?availableStart:requestedStart,end=requestedEnd>availableEnd?availableEnd:requestedEnd;if(!start||!end||start>end){$('compareMsg').textContent='LONA period is outside local MT5 history';$('compareMsg').className='bad';return}$('btStartDate').value=start;$('btEndDate').value=end;$('btBalance').value=1000;$('btRisk').value=0.5;$('btRR').value=2;$('btMaxOpen').value=1;const clipped=start!==requestedStart||end!==requestedEnd;$('compareMsg').textContent=clipped?'Using the overlapping MT5 history window; exact date parity is not possible yet.':'Running continuous Stable-Baseline parity…';$('compareMsg').className=clipped?'warn':'muted';const result=await replay('MODEL_BASELINE');if(result&&!clipped){$('compareMsg').textContent='Continuous matched-period comparison complete.';$('compareMsg').className='ok'}}

$('saveBtn').onclick=save;$('researchPresetBtn').onclick=applyResearchPreset;$('recommendBtn').onclick=applyRec;$('runBt').onclick=()=>replay('CURRENT');$('refreshLona').onclick=loadLona;$('runLonaPeriod').onclick=runLonaPeriod;load();
</script></body></html>'''
